/* SAQI-MD — x4: curated 10,000 command pack (sab REAL handlers, v5.3)
 * Families: currency pairs (<cur>2<cur>), unit pairs (<u>2<u>), city clocks (time<city>),
 * namaz timings (namaz<city>), wikipedia per language (wik<lang>), translate per language (tr<lang>),
 * facts/jokes/quotes (curated). NAMES/CATOF generator-injected.
 */
const { kvGet, kvSet, xfetch, safeMath } = require('../lib/xhelp');

const sleep = (ms) => new Promise(r => setTimeout(r, ms));

/* ---------- currency ---------- */
const CCY = new Set(Object.keys(global.__X4_CCY || {}));
const RATE_CACHE = new Map(); // base -> {rates, at}
async function ratesFor(base) {
  const c = RATE_CACHE.get(base);
  if (c && Date.now() - c.at < 600000) return c.rates;
  const txt = await xfetch('https://open.er-api.com/v6/latest/' + base).then(r => r.text());
  const j = JSON.parse(txt);
  if (!j || !j.rates) throw new Error('rate API fail');
  RATE_CACHE.set(base, { rates: j.rates, at: Date.now() });
  return j.rates;
}
async function curCmd(m, sock, name) {
  const mt = name.match(/^([a-z]{3})2([a-z]{3})$/);
  const from = mt[1].toUpperCase(), to = mt[2].toUpperCase();
  const amtM = String(m.arg || '').match(/[\d.]+/);
  const amt = amtM ? parseFloat(amtM[0]) : 1;
  const r = await ratesFor(from);
  if (!r[to]) return m.reply('❌ ' + to + ' rate nahi mila.');
  const out = amt * r[to];
  return m.reply('💱 *' + from + ' → ' + to + '*\n' + amt + ' ' + from + ' = ' + (Math.round(out * 100) / 100) + ' ' + to + '\n▫️ 1 ' + from + ' = ' + r[to] + ' ' + to + '\n▫️ Live rate (er-api, 10min cache)');
}

/* ---------- units ---------- */
const UT = {
  length: { m:1, km:1000, cm:.01, mm:.001, mi:1609.344, ft:.3048, yd:.9144, inch:.0254 },
  weight: { kg:1, g:.001, mg:1e-6, ton:1000, lb:.45359237, oz:.0283495231 },
  data: { kb:.001, mb:1, gb:1000, tb:1e6 },
  speed: { kmh:1, mph:1.609344, ms:3.6 },
  volume: { l:1, ml:.001, gal:3.785411784 },
  area: { m2:1, km2:1e6, acre:4046.8564224, ha:10000, ft2:.09290304 },
  timespan: { sec:1, min:60, hr:3600, day:86400, week:604800, yr:31557600 },
};
const UMAP = {};
for (const t in UT) for (const u in UT[t]) UMAP[u] = { t, f: UT[t][u] };
function unitCmd(m, sock, name) {
  const mt = name.match(/^([a-z0-9]+)2([a-z0-9]+)$/);
  const a = UMAP[mt[1]], b = UMAP[mt[2]];
  if (!a || !b || a.t !== b.t) return m.reply('❌ Ye units convert nahi ho saktin (' + mt[1] + ' → ' + mt[2] + ').');
  const amtM = String(m.arg || '').match(/-?[\d.]+/);
  const amt = amtM ? parseFloat(amtM[0]) : 1;
  const res = amt * a.f / b.f;
  return m.reply('🔄 *' + mt[1] + ' → ' + mt[2] + '*\n' + amt + ' ' + mt[1] + ' = ' + (Math.round(res * 1e6) / 1e6) + ' ' + mt[2]);
}
function tempCmd(m, sock, name) {
  const mt = name.match(/^([cfk])2([cfk])$/);
  const amtM = String(m.arg || '').match(/-?[\d.]+/);
  const v = amtM ? parseFloat(amtM[0]) : 0;
  const f = mt[1], t = mt[2];
  const toC = f === 'c' ? v : f === 'f' ? (v - 32) * 5 / 9 : v - 273.15;
  const out = t === 'c' ? toC : t === 'f' ? toC * 9 / 5 + 32 : toC + 273.15;
  return m.reply('🌡️ ' + v + '°' + f.toUpperCase() + ' = ' + (Math.round(out * 100) / 100) + '°' + t.toUpperCase());
}

/* ---------- city clocks ---------- */
const TZC = () => global.__X4_TZ || {};
function timeCityCmd(m, sock, name) {
  const city = name.slice(4);
  const tz = TZC()[city];
  if (!tz) return m.reply('❌ ' + city + ' ka timezone nahi pata.');
  const now = new Date().toLocaleString('en-GB', { timeZone: tz, dateStyle: 'medium', timeStyle: 'short' });
  return m.reply('🕐 *' + city.toUpperCase() + '*\n' + now + '\n▫️ Timezone: ' + tz);
}

/* ---------- namaz ---------- */
const NAMAZ = () => global.__X4_NAMAZ || {};
async function namazCmd(m, sock, name) {
  const city = name.slice(5);
  const e = NAMAZ()[city];
  if (!e) return m.reply('❌ ' + city + ' ki timings nahi pata.');
  const j = await xfetch('https://api.aladhan.com/v1/timingsByCity?city=' + encodeURIComponent(e[0]) + '&country=' + encodeURIComponent(e[1]) + '&method=1').then(r => r.text()).then(JSON.parse);
  const t = j && j.data && j.data.timings;
  if (!t) throw new Error('timings nahi mile');
  return m.reply('🕌 *NAMAZ — ' + city.toUpperCase() + '*\n' +
    'Fajr: ' + t.Fajr + ' | Dhuhr: ' + t.Dhuhr + '\nAsr: ' + t.Asr + ' | Maghrib: ' + t.Maghrib + '\nIsha: ' + t.Isha + ' | Sunrise: ' + t.Sunrise + '\n▫️ ' + (j.data.date ? j.data.date.readable : ''));
}

/* ---------- wikipedia per language ---------- */
const WLANG = () => global.__X4_WLANG || {};
async function wikiCmd(m, sock, name) {
  const lang = WLANG()[name];
  const q = String(m.arg || '').trim();
  if (!q) return m.reply('📖 .' + name + ' <topic> — ' + lang + ' Wikipedia se summary.\nExample: .' + name + ' Pakistan');
  const u0 = 'https://' + lang + '.wikipedia.org/w/api.php?action=query&prop=extracts&exintro&explaintext&format=json&formatversion=2&redirects=1&titles=' + encodeURIComponent(q.split(/\s+/).join('_'));
  let j = await xfetch(u0).then(r => r.text()).then(t => { try { return JSON.parse(t); } catch { return null; } });
  let pg = j && j.query && j.query.pages && j.query.pages[0];
  // title nahi mila (doosri zubaan) — pehle search karo, phir us page ka extract lo
  if (!pg || pg.missing || !pg.extract) {
    const s = await xfetch('https://' + lang + '.wikipedia.org/w/api.php?action=query&list=search&srsearch=' + encodeURIComponent(q) + '&format=json&formatversion=2&srlimit=1').then(r => r.text()).then(t => { try { return JSON.parse(t); } catch { return null; } });
    const hit = s && s.query && s.query.search && s.query.search[0];
    if (!hit) return m.reply('❌ "' + q + '" par kuch nahi mila (' + lang + ' wiki).');
    j = await xfetch('https://' + lang + '.wikipedia.org/w/api.php?action=query&prop=extracts&exintro&explaintext&format=json&formatversion=2&redirects=1&titles=' + encodeURIComponent(hit.title)).then(r => r.text()).then(t => { try { return JSON.parse(t); } catch { return null; } });
    pg = j && j.query && j.query.pages && j.query.pages[0];
  }
  if (!pg || !pg.extract) return m.reply('❌ "' + q + '" par kuch nahi mila (' + lang + ' wiki).');
  return m.reply('📖 *' + pg.title + '* (' + lang + ' Wikipedia)\n\n' + String(pg.extract).slice(0, 900) + '\n🔗 https://' + lang + '.wikipedia.org/wiki/' + encodeURIComponent(String(pg.title).split(/\s+/).join('_')));
}

/* ---------- translate per language ---------- */
const TLANG = () => global.__X4_TLANG || {};
async function trCmd(m, sock, name) {
  const code = TLANG()[name];
  const q = String(m.arg || '').trim();
  if (!q) return m.reply('🌐 .' + name + ' <text> — ' + name.slice(2) + ' me translate.\nExample: .' + name + ' kaise ho bhai');
  const u = 'https://api.mymemory.translated.net/get?q=' + encodeURIComponent(q.slice(0, 400)) + '&langpair=en|' + code;
  const j = await xfetch(u).then(r => r.text()).then(t => { try { return JSON.parse(t); } catch { return null; } });
  const tr = j && j.responseData && j.responseData.translatedText;
  return m.reply('🌐 *' + name.slice(2).toUpperCase() + '*\n' + (tr ? tr : '❌ translate fail'));
}

/* ---------- facts / jokes / quotes ---------- */
function pickA(arr) { return arr[Math.floor(Math.random() * arr.length)]; }
function factCmd(m, sock, name) {
  const arr = (global.__X4_FACTS || {})[name] || ['ℹ️ Content load nahi hua.'];
  return m.reply('💡 ' + pickA(arr));
}
function jokeCmd(m, sock, name) {
  const arr = (global.__X4_JOKES || {})[name] || ['😅 Content load nahi hua.'];
  return m.reply('😂 ' + pickA(arr));
}
function quoteCmd(m, sock, name) {
  const arr = (global.__X4_QUOTES || {})[name] || ['❝ Content load nahi hua.'];
  const q = pickA(arr);
  return m.reply('❝ ' + q[0] + '\n— ' + q[1]);
}

/* ---------- dispatcher ---------- */
async function dispatch(m, sock) {
  const name = m.command;
  const cat = CATOF[name] || 'GENERAL';
  try {
    if (cat === 'CURRENCY') return await curCmd(m, sock, name);
    if (cat === 'TEMPERATURE') return tempCmd(m, sock, name);
    if (cat === 'UNITS') return unitCmd(m, sock, name);
    if (cat === 'TIME') return timeCityCmd(m, sock, name);
    if (cat === 'ISLAMIC') return await namazCmd(m, sock, name);
    if (cat === 'WIKI') return await wikiCmd(m, sock, name);
    if (cat === 'TRANSLATE') return await trCmd(m, sock, name);
    if (cat === 'FACTS') return factCmd(m, sock, name);
    if (cat === 'JOKES') return jokeCmd(m, sock, name);
    if (cat === 'QUOTES') return quoteCmd(m, sock, name);
    return m.reply('ℹ️ ' + (DESC[name] || ''));
  } catch (e) {
    return m.reply('❌ ' + name + ': ' + (e.message || e) + '\nThori dair baad try karo.');
  }
}


